<template>
 <div class="overview-charts"><p v-if="drawError" role="status">{{ drawError }}</p>
  <section class="chart-panel"><header><h2>服务状态分布</h2><router-link to="/services">查看服务 →</router-link></header><p class="chart-note">当前范围的最近探测状态，未知和停用单独统计。</p><p v-if="!servicesKnown">服务快照暂不可用</p><p v-else-if="!services.length">暂无匹配服务</p><div v-show="servicesKnown && services.length" ref="statusElement" class="status-chart" role="img" :aria-label="statusDescription"></div><div v-if="servicesKnown" class="status-legend"><span v-for="s in statuses" :key="s.key"><i :style="{background:s.color}"></i>{{ s.label }} <strong>{{ s.count }}</strong></span></div></section>
  <section class="chart-panel"><header><h2>主机资源对比</h2><router-link to="/hosts">查看主机 →</router-link></header><p class="chart-note">CPU / 内存 / 磁盘使用率；按最高使用率排序。过期、异常和缺失指标显示暂无数据。</p><p v-if="!hostsKnown">主机快照暂不可用</p><p v-else-if="!hosts.length">暂无匹配主机</p><p v-else-if="!hosts.some(h=>[h.cpu,h.memory,h.disk].some(v=>v!=null))">暂无有效资源采样，请展开指标数值查看原因。</p><div v-show="hostsKnown && hosts.length" ref="hostElement" class="host-chart" role="img" aria-label="当前范围各主机 CPU、内存、磁盘使用率对比，点击可查看主机详情"></div><details v-if="hosts.length" class="metric-values"><summary>查看指标数值</summary><div class="table-wrap"><table><thead><tr><th>主机</th><th>CPU</th><th>内存</th><th>磁盘</th><th>采集状态</th></tr></thead><tbody><tr v-for="h in sortedHosts" :key="h.id"><td><router-link :to="'/hosts/'+h.id">{{ h.name }}</router-link></td><td v-for="m in metrics" :key="m.key">{{ format(h[m.key]) }}</td><td>{{ h.quality || '采集正常' }}</td></tr></tbody></table></div></details></section>
 </div>
</template>
<script setup>
import {computed,ref,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
const props=defineProps({services:{type:Array,default:()=>[]},hosts:{type:Array,default:()=>[]},servicesKnown:Boolean,hostsKnown:Boolean})
const router=useRouter(),statusElement=ref(null),hostElement=ref(null),drawError=ref('')
const metrics=[{key:'cpu',label:'CPU',color:'#1689e7'},{key:'memory',label:'内存',color:'#27a981'},{key:'disk',label:'磁盘',color:'#e3a23e'}]
const statuses=computed(()=>[{key:'UP',label:'正常',color:'#27a981'},{key:'DOWN',label:'异常',color:'#df6158'},{key:'UNKNOWN',label:'未知',color:'#9aa8ba'},{key:'DISABLED',label:'停用',color:'#d7dee6'}].map(s=>({...s,count:props.services.filter(row=>(row.enabled===false?'DISABLED':['UP','DOWN'].includes(row.last_status)?row.last_status:'UNKNOWN')===s.key).length})))
const statusDescription=computed(()=>statuses.value.map(s=>s.label+' '+s.count).join('，'))
const sortedHosts=computed(()=>props.hosts.slice().sort((a,b)=>Math.max(b.cpu??-1,b.memory??-1,b.disk??-1)-Math.max(a.cpu??-1,a.memory??-1,a.disk??-1)))
const format=v=>v==null?'暂无数据':Number(v).toFixed(1)+'%'
const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
let statusChart,hostChart,observer,echarts,version=0,disposed=false
async function draw(){drawError.value='';const current=++version;await nextTick();const library=echarts || await import('echarts');if(disposed||current!==version)return;echarts=library
 if(!statusChart){statusChart=echarts.init(statusElement.value);hostChart=echarts.init(hostElement.value);hostChart.on('click',event=>{if(event.data?.hostId!=null)router.push('/hosts/'+event.data.hostId)});observer=new ResizeObserver(()=>{statusChart?.resize();hostChart?.resize()});observer.observe(statusElement.value);observer.observe(hostElement.value)}
 statusChart.setOption({tooltip:{trigger:'item',formatter:p=>escape(p.name)+'：'+p.value+' 个'},title:{text:String(props.services.length),subtext:'服务实例',left:'center',top:'38%',textStyle:{fontSize:30,color:'#263746'},subtextStyle:{fontSize:12,color:'#708295'}},series:[{type:'pie',radius:['58%','78%'],center:['50%','48%'],label:{show:false},data:statuses.value.map(s=>({name:s.label,value:s.count,itemStyle:{color:s.color}})),emphasis:{scaleSize:5}}]},true)
 const rows=sortedHosts.value
 hostChart.setOption({animation:false,legend:{data:metrics.map(m=>m.label),top:0,right:10,textStyle:{fontSize:11}},grid:{top:35,left:110,right:rows.length>12?45:25,bottom:28},tooltip:{trigger:'axis',axisPointer:{type:'shadow'},formatter:items=>{const host=rows[items[0]?.dataIndex];return host?'<strong>'+escape(host.name)+'</strong><br>'+metrics.map(m=>escape(m.label)+'：'+format(host[m.key])).join('<br>')+'<br>'+escape(host.quality || '采集正常')+'<br>'+escape(host.checkedAt || '暂无采集时间'):''}},xAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%',fontSize:10},splitLine:{lineStyle:{color:'#eaf0f5'}}},yAxis:{type:'category',inverse:true,data:rows.map(h=>h.name),axisLabel:{width:95,overflow:'truncate',fontSize:10},axisTick:{show:false},axisLine:{show:false}},dataZoom:rows.length>12?[{type:'slider',yAxisIndex:0,right:3,startValue:0,endValue:11,filterMode:'empty',width:12}]:[],series:metrics.map(m=>({name:m.label,type:'bar',barMaxWidth:9,itemStyle:{color:m.color,borderRadius:[0,3,3,0]},data:rows.map(h=>({value:h[m.key],hostId:h.id})),label:{show:rows.length<=6,position:'right',fontSize:9,formatter:p=>format(p.value)}}))},true)
 statusChart.resize();hostChart.resize()
}
function render(){draw().catch(()=>{if(disposed)return;drawError.value='图表暂时无法加载，请刷新重试';observer?.disconnect();statusChart?.dispose();hostChart?.dispose();statusChart=null;hostChart=null})}
watch(()=>[props.services,props.hosts,props.servicesKnown,props.hostsKnown],render)
onMounted(render);onBeforeUnmount(()=>{disposed=true;version++;observer?.disconnect();statusChart?.dispose();hostChart?.dispose()})
</script>
<style scoped>
.overview-charts{display:grid;grid-template-columns:minmax(250px,.7fr) minmax(0,1.3fr);gap:12px;margin-bottom:12px}.chart-panel{min-width:0;padding:14px;background:white;border:1px solid #dce7f4;border-radius:5px}.chart-panel header{display:flex;align-items:center;justify-content:space-between;gap:12px}.chart-panel h2{font-size:15px;color:#173958;margin:0}.chart-panel a{font-size:12px;color:#16738c;text-decoration:none}.chart-note,.chart-panel p{font-size:11px;color:#708295;line-height:1.7}.status-chart,.host-chart{height:305px}.status-legend{display:flex;flex-wrap:wrap;justify-content:center;gap:14px;font-size:12px;color:#617482}.status-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}.status-legend strong{color:#263746}.metric-values{font-size:11px;color:#708295;margin-top:10px}.metric-values summary{cursor:pointer}.metric-values table{width:100%;border-collapse:collapse;margin-top:8px}.metric-values th,.metric-values td{text-align:left;padding:6px;border-bottom:1px solid #edf2f7;white-space:nowrap}@media(max-width:950px){.overview-charts{grid-template-columns:1fr}.status-chart{height:240px}}@media(max-width:600px){.chart-panel{padding:12px}.host-chart{height:330px}.status-legend{gap:10px}}
</style>
